*{box-sizing:border-box} :root{--gold:#d7b678;--gold-bright:#f4dba4;--muted:#8d929c;--blood:#b54b52;--ink:#090b10;--panel:rgba(11,14,20,.78)}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#090b10;color:#e8e4de;font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}#game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#0a0c11}canvas{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 49%,transparent 35%,rgba(3,5,9,.2) 72%,rgba(3,5,9,.74) 130%),linear-gradient(180deg,rgba(5,7,10,.5),transparent 20%,transparent 65%,rgba(5,7,10,.55);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:74px;padding:0 40px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(215,182,120,.12);background:linear-gradient(180deg,rgba(8,10,14,.82),transparent)}.brand{font-family:Cinzel,serif;letter-spacing:.23em;font-size:15px;font-weight:600;display:flex;align-items:center;gap:12px}.brand-mark{color:var(--gold);font-size:21px}.brand i{font:500 9px 'DM Sans';letter-spacing:.2em;color:#9da0a4;margin-left:2px}.mission{font-size:10px;letter-spacing:.2em;color:#d9d4c9;font-weight:600;display:flex;align-items:center;gap:9px}.live-dot{height:6px;width:6px;border-radius:50%;background:#c9a66c;box-shadow:0 0 10px #d4ae71}.icon-btn{width:37px;height:37px;color:#ddd5c5;background:rgba(15,18,24,.55);border:1px solid rgba(215,182,120,.3);font-size:17px;border-radius:50%;cursor:pointer}.hud-left{position:absolute;z-index:3;top:104px;left:40px;width:275px}.character-row{display:flex;align-items:center;gap:13px;margin-bottom:23px}.portrait{width:53px;height:53px;border:1px solid rgba(216,182,120,.7);background:linear-gradient(140deg,#333440,#15171e 54%,#6c4a4b);display:grid;place-items:center;transform:rotate(45deg);box-shadow:0 0 24px #a9773f33}.portrait span{transform:rotate(-45deg);font-family:Cinzel;color:#e7d2a4;font-size:24px}.eyebrow{font-size:9px;letter-spacing:.22em;color:#c5a872;font-weight:600}.identity h1{font:600 19px Cinzel;margin:4px 0 2px;letter-spacing:.09em}.level-line{font-size:9px;letter-spacing:.16em;color:#999ba0}.level-line b{color:#e2c48e;font-weight:600}.bar-wrap{margin-bottom:13px}.bar-label{display:flex;justify-content:space-between;margin-bottom:6px;font-size:9px;letter-spacing:.19em;color:#c4c0b9}.bar-label span:last-child{color:#aaa9a5;letter-spacing:.08em}.bar{height:5px;background:rgba(238,232,224,.13);position:relative;overflow:hidden}.bar i{display:block;height:100%;width:100%;transition:width .25s ease;background:linear-gradient(90deg,#792f38,#c66b64);box-shadow:0 0 12px #bc545255}.bar.essence{height:3px}.bar.essence i{width:45%;background:linear-gradient(90deg,#6253a0,#bba3e8);box-shadow:0 0 12px #a491e4}.party-switch{display:flex;gap:6px;margin-top:24px;padding-top:12px;border-top:1px solid #d5bd8830}.party-label{font-size:8px;letter-spacing:.16em;color:#8f8e8d;position:absolute;margin-top:-22px}.party-slot{flex:1;background:rgba(12,14,19,.47);border:1px solid rgba(210,205,190,.13);height:44px;color:#89898a;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;position:relative;cursor:pointer;transition:.2s}.party-slot b{font:600 9px Cinzel;letter-spacing:.1em}.party-slot span{font-size:8px;letter-spacing:.12em}.party-slot.active{border-color:#cfad77;color:#e6d3ac;background:#a47f4225}.party-slot.active i{position:absolute;width:4px;height:4px;background:var(--gold);bottom:-3px;border-radius:50%}.objective{position:absolute;z-index:3;left:40px;bottom:44px;display:flex;gap:13px;align-items:center}.objective-icon{font-size:22px;color:var(--gold);border-right:1px solid #d8bc8247;padding-right:13px}.objective strong{display:block;font:600 12px Cinzel;letter-spacing:.09em;margin:4px 0}.objective small{font-size:10px;color:#aaa9a5;letter-spacing:.02em}.objective small span{color:#e3c18a}.combat-readout{position:absolute;z-index:3;right:43px;bottom:42px;display:flex;align-items:center;gap:20px;opacity:.88}.style-rank{display:flex;gap:10px;align-items:center}.style-rank>span{font:500 52px Cinzel;color:#d7bd88;line-height:1;text-shadow:0 0 22px #bb985b66}.style-rank b{font:600 11px Cinzel;letter-spacing:.13em;color:#e7d7b5;display:block}.style-rank small{font-size:8px;letter-spacing:.17em;color:#92918d}.combo-read{display:flex;align-items:center;gap:7px;border-left:1px solid #d7bd8844;padding-left:17px}.combo-read b{font:500 28px Cinzel;color:#eee4d0}.combo-read span{font-size:8px;letter-spacing:.14em;color:#aaa}.boss-hud{position:absolute;z-index:3;top:93px;left:50%;transform:translateX(-50%);width:min(440px,65vw);text-align:center}.boss-name{display:flex;align-items:center;justify-content:center;gap:8px;margin-bottom:7px}.boss-name>span{font-size:12px;color:#d4a875}.boss-name b{font:600 11px Cinzel;letter-spacing:.16em}.boss-name small{font-size:8px;letter-spacing:.1em;color:#d6a5a1;margin-left:8px}.bossbar{height:7px;border:1px solid #a34a4e77;background:#200f15}.bossbar i{width:100%;background:linear-gradient(90deg,#6e1d2e,#df5a5c);box-shadow:0 0 13px #d4344977;transition:width .22s}.hidden{display:none!important}.toast{position:absolute;z-index:8;top:84px;left:50%;transform:translate(-50%,-12px);padding:11px 22px;border:1px solid #d9b87666;background:rgba(9,11,15,.9);font:500 10px Cinzel;letter-spacing:.14em;color:#e8d6b1;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.center-message{position:absolute;z-index:4;left:50%;top:43%;transform:translate(-50%,-50%);text-align:center;font:500 clamp(20px,4vw,36px) Cinzel;letter-spacing:.18em;color:#f0dfbd;text-shadow:0 0 28px #d7a45099;opacity:0;transition:.5s;pointer-events:none;white-space:nowrap}.center-message.show{opacity:1}.controls-hint{position:absolute;z-index:3;bottom:19px;left:50%;transform:translateX(-50%);white-space:nowrap;font-size:8px;letter-spacing:.17em;color:#a6a4a0}.controls-hint span{color:#e4d7bd;font-weight:700}.controls-hint i{font-style:normal;color:#766f65;margin:0 8px}.overlay{position:absolute;z-index:10;inset:0;background:rgba(5,7,11,.42);display:grid;place-items:center}.title-backdrop{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,rgba(13,15,20,.32),rgba(4,6,9,.82) 75%),linear-gradient(90deg,rgba(5,7,10,.45),transparent 48%,rgba(5,7,10,.4)}.title-content{position:relative;text-align:center;margin-top:-1vh;width:min(560px,90vw);animation:rise .9s ease both}.crest{font-size:26px;color:#d7b678;text-shadow:0 0 24px #d6ad66;margin-bottom:12px}.title-kicker{font-size:9px;letter-spacing:.32em;color:#d4b77f;margin:0 0 4px}.title-content h2{font:500 clamp(62px,11vw,100px)/1 Cinzel;margin:0;color:#e8e3d8;letter-spacing:.17em;text-shadow:0 5px 35px #0a0a0a}.title-sub{font:500 13px Cinzel;letter-spacing:.35em;color:#d5c6a9;margin-top:5px}.title-copy{font-size:12px;line-height:1.9;color:#b8b4ad;margin:24px 0 26px}.primary-btn{position:relative;display:flex;align-items:center;justify-content:center;gap:27px;margin:auto;padding:0 22px;height:48px;min-width:260px;background:linear-gradient(110deg,#b79a65,#e1ca9c 50%,#b3935f);border:1px solid #e8d5ae;color:#171510;font:700 10px 'DM Sans';letter-spacing:.15em;cursor:pointer;box-shadow:0 5px 30px #c19b4d25;transition:.2s}.primary-btn:hover{filter:brightness(1.13);transform:translateY(-2px);box-shadow:0 8px 34px #c19b4d4a}.primary-btn b{font-size:18px;font-weight:400}.title-foot{margin:27px 0 18px;font-size:8px;letter-spacing:.2em;color:#787977}.title-foot span{color:#cfad77;margin:0 9px}.title-controls{display:flex;justify-content:center;gap:18px;color:#d2c7af;font-size:8px;letter-spacing:.08em}.title-controls i{display:block;font-style:normal;color:#777875;font-size:7px;letter-spacing:.16em;margin-top:3px}.pause-overlay,.end-overlay{background:rgba(4,6,10,.74);backdrop-filter:blur(6px)}.pause-card{width:min(420px,90vw);padding:42px 38px;text-align:center;background:linear-gradient(150deg,rgba(23,25,30,.97),rgba(10,12,16,.97));border:1px solid #d1ad6d56;box-shadow:0 20px 70px #0009;animation:rise .35s ease both}.pause-card h2{font:500 42px Cinzel;letter-spacing:.13em;margin:7px 0 11px}.pause-card>p:not(.eyebrow){font-size:12px;color:#aaa6a0;margin:0 0 24px}.pause-secondary{display:flex;justify-content:center;gap:20px;margin-top:22px}.pause-secondary button,.restart-link{background:none;border:0;color:#a29d91;font-size:9px;letter-spacing:.13em;cursor:pointer}.pause-secondary button:hover,.restart-link:hover{color:#edce91}.reward-row{display:flex;align-items:center;justify-content:center;gap:13px;padding:14px;border:1px solid #d3b57844;margin:0 0 21px;text-align:left}.reward-row>span{font-size:23px;color:#ddc186}.reward-row b{display:block;font:600 10px Cinzel;letter-spacing:.1em}.reward-row small{font-size:8px;color:#a7a29a;letter-spacing:.12em}.restart-link{display:block;margin:16px auto 0}.touch-controls{display:none;position:absolute;z-index:5;inset:auto 0 20px;height:155px;align-items:flex-end;justify-content:space-between;padding:0 max(22px,env(safe-area-inset-left)) 0 max(22px,env(safe-area-inset-right));pointer-events:none}.move-pad{width:128px;height:128px;pointer-events:auto;touch-action:none}.pad-ring{width:116px;height:116px;border:1px solid #d8c49b63;border-radius:50%;background:rgba(14,17,22,.3);display:grid;place-items:center;box-shadow:inset 0 0 25px #0a0a0a77}.pad-knob{width:48px;height:48px;border-radius:50%;background:linear-gradient(145deg,#c8b184aa,#433b32aa);border:1px solid #e0cba27a;box-shadow:0 4px 12px #0008;transform:translate(0,0)}.touch-actions{display:flex;align-items:flex-end;gap:11px;pointer-events:auto;padding-bottom:5px}.touch-action{border-radius:50%;display:grid;place-content:center;justify-items:center;gap:0;color:#f1e4c8;background:radial-gradient(circle at 35% 25%,#3a3430dd,#12151bcc);border:1px solid #c5a66c88;box-shadow:0 5px 18px #0008;touch-action:none;cursor:pointer}.touch-action span{font-size:24px;line-height:1.05}.touch-action small{font-size:7px;letter-spacing:.12em;color:#d0c0a0}.touch-action.attack{width:68px;height:68px;border-color:#d7b473}.touch-action.dodge{width:54px;height:54px}.touch-action.skill{width:58px;height:58px;border-color:#a89bd1}.touch-action:active{filter:brightness(1.5);transform:scale(.94)}@keyframes rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:720px){.topbar{height:57px;padding:0 17px}.brand{font-size:12px;gap:7px}.brand i{display:none}.mission{font-size:8px;letter-spacing:.1em}.icon-btn{width:33px;height:33px}.hud-left{top:72px;left:18px;width:205px}.character-row{gap:9px;margin-bottom:15px}.portrait{width:39px;height:39px}.portrait span{font-size:19px}.identity h1{font-size:15px}.eyebrow{font-size:8px}.level-line{font-size:8px}.bar-wrap{margin-bottom:9px}.bar-label{font-size:8px}.party-switch{margin-top:19px;gap:4px}.party-slot{height:36px}.party-slot b{font-size:8px}.party-slot span{font-size:7px}.party-label{font-size:7px;margin-top:-18px}.objective{left:18px;bottom:176px;gap:9px}.objective-icon{font-size:19px;padding-right:9px}.objective strong{font-size:10px}.objective small{font-size:9px}.combat-readout{right:18px;bottom:175px;gap:10px}.style-rank>span{font-size:37px}.style-rank b{font-size:9px}.style-rank small{font-size:7px}.combo-read{padding-left:9px;gap:5px}.combo-read b{font-size:23px}.combo-read span{font-size:7px}.controls-hint{display:none}.touch-controls{display:flex}.boss-hud{top:69px;width:68vw}.boss-name b{font-size:9px}.boss-name small{font-size:7px}.bossbar{height:6px}.title-controls{gap:12px}.title-copy{font-size:11px}.title-foot{font-size:7px}.pause-card{padding:33px 25px}.center-message{top:42%}}
@media(max-height:560px) and (orientation:landscape){.touch-controls{bottom:8px;height:100px}.move-pad{width:98px;height:98px}.pad-ring{width:90px;height:90px}.pad-knob{width:40px;height:40px}.touch-actions{gap:7px}.touch-action.attack{width:58px;height:58px}.touch-action.dodge,.touch-action.skill{width:49px;height:49px}.touch-action span{font-size:20px}.objective,.combat-readout{bottom:12px}.hud-left{top:70px}.character-row{margin-bottom:9px}.party-switch{margin-top:16px}.boss-hud{top:67px}.title-content{transform:scale(.82)}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game-canvas');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x11151d);
scene.fog=new THREE.FogExp2(0x11151d,0.023);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,140);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
scene.add(new THREE.HemisphereLight(0x9ca9c8,0x211c1d,1.65));
const moon=new THREE.DirectionalLight(0xb9c6e4,2.1);moon.position.set(-8,15,7);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-22;moon.shadow.camera.right=22;moon.shadow.camera.top=22;moon.shadow.camera.bottom=-22;scene.add(moon);
const redLight=new THREE.PointLight(0xb4323b,27,24,2);redLight.position.set(1,5,-12);scene.add(redLight);
const goldLight=new THREE.PointLight(0xd9a65a,22,18,2);goldLight.position.set(-13,4,0);scene.add(goldLight);
const mat=(color,roughness=.7,metalness=0,emissive=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:emissive?1.5:0});
const M={stone:mat(0x353942,.93),stone2:mat(0x46484d,.9),dark:mat(0x151821,.62,.35),armor:mat(0x20232b,.4,.7),silver:mat(0xb9bac1,.35,.72),cloth:mat(0x171820,.96),red:mat(0x6d2632,.8),gold:mat(0xb28b52,.38,.7),bone:mat(0xb5aa98,.65),eye:mat(0xff463d,.25,.1,0x8e1215),blue:mat(0x8094d9,.25,.2,0x344cbb),violet:mat(0xb29bdf,.28,.2,0x7055c5),ground:mat(0x282b30,.98)};
function box(parent,x,y,z,sx,sy,sz,material,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.SphereGeometry(1,12,10),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,rt,rb,h,material,segments=8){const m=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
// Ashen courtyard: cracked flagstones, reliquaries, broken gothic ribs and a distant keep.
const floor=new THREE.Mesh(new THREE.PlaneGeometry(90,90),M.ground);floor.rotation.x=-Math.PI/2;floor.position.y=-.09;floor.receiveShadow=true;scene.add(floor);
const grid=new THREE.GridHelper(88,44,0x4b4c50,0x34363b);grid.position.y=-.075;grid.material.transparent=true;grid.material.opacity=.17;scene.add(grid);
for(let i=0;i<130;i++){const x=(Math.random()-.5)*68,z=(Math.random()-.5)*58; if(Math.abs(x)<4&&Math.abs(z)<5)continue;const s=.35+Math.random()*1.7;const stone=box(scene,x,-.025+Math.random()*.025,z,s,.08+Math.random()*.05,s*.6,M.stone,0,Math.random()*Math.PI,0);stone.material=Math.random()>.65?M.stone2:M.stone;}
// Gothic ruined columns and broken walls frame the arena.
function pillar(x,z,h=5,broken=false){const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);cylinder(g,0,h/2,0,.62,.75,h,M.stone2,8);for(let y=.4;y<h;y+=1.25)cylinder(g,0,y,0,.79,.79,.12,M.stone,8);cylinder(g,0,h,0,.95,.73,.4,M.stone2,8);if(broken){box(g,.2,h+.65,0,.55,1.5,.6,M.stone2,.22,0,-.4);box(g,-.15,h+.2,.08,.8,.42,.8,M.stone,0,.2,.3)}else{const tip=cylinder(g,0,h+1.05,0,0,.46,1.7,M.stone2,8);tip.rotation.z=Math.PI;}}
[[-12,-11,6,true],[-6,-15,8,false],[6,-16,7,true],[13,-11,5,false],[-15,1,7,false],[15,2,8,true],[-13,13,5,true],[12,14,7,false],[-20,-7,8,true],[20,-8,7,true]].forEach(p=>pillar(...p));
// Backdrop spires and silhouette walls.
for(let i=0;i<13;i++){const x=-23+i*3.8,z=-26-Math.random()*5,h=7+Math.random()*9;box(scene,x,h/2,z,2.8,h,1.6,i%3===0?M.stone2:M.dark,0,(Math.random()-.5)*.12,0);cylinder(scene,x,h+1.8,z,0,1.5,3.8,M.dark,4)}
// ominous eclipse, low haze motes
const eclipse=new THREE.Mesh(new THREE.SphereGeometry(2.4,24,20),new THREE.MeshBasicMaterial({color:0x451f2d}));eclipse.position.set(2,13,-30);scene.add(eclipse);const halo=new THREE.PointLight(0xc23243,35,45,2);halo.position.copy(eclipse.position);scene.add(halo);
const particles=[];const particleGeo=new THREE.SphereGeometry(.055,6,6);const particleMat=new THREE.MeshBasicMaterial({color:0xd9a768,transparent:true,opacity:.65});for(let i=0;i<85;i++){const p=new THREE.Mesh(particleGeo,particleMat);p.position.set((Math.random()-.5)*38,.2+Math.random()*7,(Math.random()-.5)*36);p.userData={speed:.15+Math.random()*.5,phase:Math.random()*8};scene.add(p);particles.push(p)}

const characterSpecs=[
 {name:'CAEL VANE',style:'VOIDBLADE',glyph:'✧',coat:0x171820,accent:0xb8c5dc,type:'sword',speed:7.6,hp:100,damage:18},
 {name:'BRANN VOLD',style:'IRON WRAITH',glyph:'⬟',coat:0x37302a,accent:0xd0a466,type:'heavy',speed:5.1,hp:135,damage:31},
 {name:'LYRA NOCT',style:'DUSK WEAVER',glyph:'☾',coat:0x291e34,accent:0xb8a2e8,type:'twin',speed:7.0,hp:95,damage:16}
];
function makeHero(spec){const g=new THREE.Group();const body=new THREE.Group();g.add(body);const robe=mat(spec.coat,.83,.08),accent=mat(spec.accent,.3,.45,spec.type==='twin'?0x281747:0);
 sphere(body,0,1.63,0,.32,.4,.23,M.armor);sphere(body,0,2.18,0,.23,.26,.23,M.silver); // head / hair
 sphere(body,0,2.28,-.02,.27,.25,.25,M.silver);for(let i=0;i<7;i++){const hair=sphere(body,(i-3)*.06,2.43,-.11+Math.random()*.14,.06,.22,.07,M.silver);hair.rotation.z=(i-3)*-.16}
 box(body,0,1.82,-.03,.5,.18,.3,M.gold,0,0,0); // collar trim
 box(body,-.14,1.63,.02,.11,.44,.28,M.silver,0,0,-.15);box(body,.14,1.63,.02,.11,.44,.28,M.armor,0,0,.15);
 const cape=box(body,0,1.08,-.2,.53,1.08,.12,robe,.16,0,0);cape.userData.cape=true;
 // arms
 for(const side of [-1,1]){const arm=sphere(body,side*.4,1.64,0,.13,.37,.14,M.armor);arm.rotation.z=side*-.15; sphere(body,side*.42,1.34,.02,.14,.13,.14,M.dark);box(body,side*.4,1.87,0,.24,.13,.25,accent,0,0,side*.3)}
 // long split coat tails
 box(body,-.17,.75,-.18,.19,.85,.11,robe,.1,0,-.08);box(body,.17,.75,-.18,.19,.85,.11,robe,.1,0,.08);
 for(const side of [-1,1]){box(body,side*.15,.38,0,.16,.55,.18,M.dark,0,0,side*.035);box(body,side*.15,.13,.1,.2,.16,.36,M.armor)}
 const weapon=new THREE.Group();weapon.position.set(.56,1.28,.05);weapon.rotation.x=.1;body.add(weapon);
 const length=spec.type==='heavy'?1.65:1.2,width=spec.type==='heavy'?.22:.1;
 cylinder(weapon,0,-.05,0,.045,.045,.42,M.gold,8);box(weapon,0,length*.53,0,width,length,.08,spec.type==='twin'?accent:M.silver,0,0,-.06);box(weapon,0,length*.9,0,width*.75,.25,.07,M.bone,0,0,0);box(weapon,0,.05,0,.28,.07,.12,M.gold);
 if(spec.type==='twin'){const off=weapon.clone();off.position.set(-.56,1.29,.04);off.scale.x=-1;body.add(off)}
 g.userData={body,weapon,robe};scene.add(g);g.position.set(0,0,5);return g;}
const heroes=characterSpecs.map(makeHero);let active=0;heroes.forEach((h,i)=>h.visible=i===0);let hero=heroes[0];
